# Let me try to reverse-engineer the pattern by looking at character changes

inputs = ['kvvh', 'ecxxu', 'vjai', 'kyx', 'fef']
outputs = ['kvvh', 'edfkgxxu', 'vjjuii', 'kyx', 'fef']

# Analyze each pair
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input: '{inp}' -> Output: '{out}'")
    if inp != out:
        # Find differences
        min_len = min(len(inp), len(out))
        diff = []
        for j in range(min_len):
            if inp[j] != out[j]:
                diff.append((j, inp[j], out[j]))
        if len(out) > len(inp):
            diff.append((len(inp), '', out[len(inp):]))
        elif len(inp) > len(out):
            diff.append((len(out), inp[len(out):], ''))
        print(f"  Differences: {diff}")
    print()

